import java.util.Scanner;
public class JAdjacentConsecutives {
	public static void main(String[] args) {
		//Khatwa 1: Iqra al-aadad al-awwal alladhi yadkhuluh al-mustakhdim
		System.out.println("Adkhil al-aadad mafsoola bi-masafat aw satar jadid (adkhil -1 lil-khuruj): ");
		Scanner scan = new Scanner(System.in); 
		int num = scan.nextInt();
		//Khatwa 2: Iqra baqiyat al-aadad allati yadkhuluhha al-mustakhdim wa tafaqad al-aadad al-mutajawira al-mutatabiqa
		while (num != -1) {
			int previous = num;
			num = scan.nextInt();
			if ( num != -1 && num - previous == 1 ) {
				System.out.println(previous + " " +num + " are consecutive."); 
			}
		}
		scan.close();
	}
}
